import re

def word_frequencies(text):
    words = re.findall(r"[A-Za-z0-9]+(?:'[A-Za-z0-9]+)?", text.casefold())
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    return counts

